#include <stdio.h>
#include <string.h>
#include <ctype.h>

/* Return the Soundex digit for a single (already upper‑case) character.
   0 is returned for letters that are ignored by the algorithm. */
static int soundex_digit(char c)
{
    switch (c) {
        case 'B': case 'F': case 'P': case 'V': return 1;
        case 'C': case 'G': case 'J': case 'K':
        case 'Q': case 'S': case 'X': case 'Z': return 2;
        case 'D': case 'T': return 3;
        case 'L': return 4;
        case 'M': case 'N': return 5;
        case 'R': return 6;
        default: return 0;               /* A,E,I,O,U,H,W,Y and others */
    }
}

/* Compute the Soundex code of the given string.
   The result buffer must have room for at least 5 characters
   (4 characters + terminating NUL). */
static void soundex(const char *src, char *dst)
{
    /* first letter (upper‑cased) */
    dst[0] = toupper((unsigned char)src[0]);

    int last_digit = soundex_digit(dst[0]);   /* digit of the first letter */
    int out_idx = 1;                          /* next position in dst */

    for (size_t i = 1; src[i] != '\0' && out_idx < 4; ++i) {
        char ch = toupper((unsigned char)src[i]);
        int d = soundex_digit(ch);
        if (d == 0)               /* ignored letters */
            continue;
        if (d == last_digit)      /* collapse duplicates */
            continue;
        dst[out_idx++] = (char)('0' + d);
        last_digit = d;
    }

    /* pad with zeros if we have fewer than three digits */
    while (out_idx < 4)
        dst[out_idx++] = '0';

    dst[4] = '\0';
}

int main(int argc, char *argv[])
{
    if (argc < 2 || argv[1][0] == '\0') {
        puts("EMPTY");
        return 0;
    }

    char out[5];
    soundex(argv[1], out);
    puts(out);
    return 0;
}
